@startuml

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + DateOfEmployment : date
}

class FlightAttendant extends Employee {
  + IsChiefStewardess : boolean
}

class Pilot extends Employee {
  + License : string
}

class Airplane {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspectionDate : date
}

class PassengerPlane extends Airplane {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

Airline "0..1" -- "0..*" Employee
Airline "0..1" o-- "0..*" Airplane
Airplane "0..1" -- "0..1" Airport : homeAirport
Airplane "1" -- "0..*" Flight
Flight "1" -- "0..*" Airport : departureAirport
Flight "1" -- "0..*" Airport : destinationAirport
Flight "0..*" -- "0..*" FlightAttendant
Flight "0..*" -- "1" Pilot : captain
Flight "0..*" -- "1..2" Pilot : co-pilot
PassengerPlane "1" *-- "0..*" SeatCategory
Flight "1" -- "0..*" Ticket
Passenger "1" -- "0..*" Ticket
SeatCategory "1" -- "0..*" Ticket
Passenger "0..*" -- "0..*" Flight
Passenger "0..*" -- "0..*" PassengerPlane

@enduml

